window.AUTH=window.AUTH||{};window.AUTH["21-1496"]={"d":"21-1496","id":"2022/21-1496","n":"Twitter, Inc. v. Taamneh","briefs":[{"k":"petitioner","label":"Brief of petitioner Twitter, Inc.","date":"2022-11-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1496/247605/20221129133916710_21-1496%20ts.pdf","side":"pet","n":46},{"k":"respondent","label":"Brief of respondents Facebook, Inc. and Google LLC supporting petitioners","date":"2022-11-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-1496/247601/20221129131310083_21-1496%202022-11-29%20Taamneh%20Final.pdf","side":"res","n":40},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-12-06","url":"https://www.supremecourt.gov/DocketPDF/21/21-1496/249258/20221206203311570_21-1496tsacUnitedStates.pdf","side":"us","n":29},{"k":"respondent","label":"Brief of respondents Mehier Taamneh, et al.","date":"2023-01-11","url":"https://www.supremecourt.gov/DocketPDF/21/21-1496/252104/20230111231022489_TaamnehRBrPDF.pdf","side":"res","n":62},{"k":"reply","label":"Reply of petitioner Twitter, Inc.","date":"2023-02-10","url":"https://www.supremecourt.gov/DocketPDF/21/21-1496/254539/20230210125557210_21-1496%20rb.pdf","side":"pet","n":20}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r22_hejm.pdf","tr":true,"items":[{"t":"case","label":"Page(s) American Family Mutual Insurance Co. v. Grim","cite":"440 P.2d 621","y":1968,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/440/621/","op":1,"by":{"0":"35","4":"10"}},{"t":"case","label":"BMG Rights Management (US) LLC v. Cox Communications, Inc.","cite":"881 F.3d 293","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/881/293/","by":{"0":"43"}},{"t":"case","label":"Boim v. Holy Land Foundation for Relief & Development","cite":"549 F.3d 685","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/685/","by":{"0":"8","1":"5","2":"2","3":"20"}},{"t":"case","label":"Cain v. Twitter Inc.","cite":"2018 WL 4657275","y":2018,"court":"N.D. Cal. Sept. 24","sum":"Rejecting allegations that Twitter “should have known ISIS was planning an attack” and “ignored the possible consequences of letting terrorists operate on its platform” as “in effect an allegation of recklessness”.","sumSrc":"brief:1","by":{"0":"11","1":"39"}},{"t":"case","label":"Camp v. Dema","cite":"948 F.2d 455","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/948/455/","op":4,"by":{"0":"36, 40, 44","2":"20","3":"68, 69","4":"15, 17, 18"}},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"op":3,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"23, 26, 29, 49","1":"27, 28","2":"19","3":"39"}},{"t":"case","label":"Colon v. Twitter, Inc.","cite":"14 F.4th 1213","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/14/1213/","by":{"0":"11"}},{"t":"case","label":"Copeland v. Twitter, Inc.","cite":"352 F. Supp. 3d 965","y":2018,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/352/965/","by":{"0":"11","1":"43"}},{"t":"case","label":"Crosby v. Twitter, Inc.","cite":"921 F.3d 617","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/921/617/","sum":"Explaining that a contrary holding would make social media companies “liable for seemingly endless acts of modern violence”.","sumSrc":"brief:2","by":{"0":"11, 48","2":"23"}},{"t":"case","label":"Duke v. Feldman","cite":"226 A.2d 345","y":1967,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/226/345/","op":2,"by":{"0":"27","3":"39"}},{"t":"case","label":"Fields v. Twitter, Inc.","cite":"881 F.3d 739","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/881/739/","by":{"0":"7, 48","2":"7"}},{"t":"case","label":"Force v. Facebook, Inc.","cite":"934 F.3d 53","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/934/53/","by":{"0":"11"}},{"t":"case","label":"Page(s) Gallardo by and through Vasallo v. Marstiller","cite":"142 S. Ct. 1751","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Gonnella v. SEC","cite":"954 F.3d 536","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/954/536/","by":{"0":"28"}},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","op":60,"ar":46,"sum":"Finding that Hamilton “knew she was assisting Welch’s wrongful acts”.","sumSrc":"brief:2","by":{"0":"passim","1":"passim","2":"passim","3":"49, 58, 63, 64, 67, 68, 70, 71, 77-79","4":"4, 10, 11, 12, 15, 19, 20, 23"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"8","1":"25","3":"43, 46, 53, 57, 58"}},{"t":"case","label":"Holmes v. Securities Investor Protection Corp.","cite":"503 U.S. 258","y":1992,"id":"1991/90-727","sc":1,"sum":"SIPC has demonstrated no right to sue Holmes under § 1964(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7"}},{"t":"case","label":"Investors Research Corp. v. SEC","cite":"628 F.2d 168","y":1980,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/628/168/","by":{"0":"40","2":"18"}},{"t":"case","label":"Kaplan v. Lebanese Canadian Bank","cite":"999 F.3d 842","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/999/842/","ar":5,"by":{"0":"46","2":"21, 22","3":"18, 25","4":"20"}},{"t":"case","label":"Keel v. Hainline","cite":"331 P.2d 397","y":1958,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/331/397/","sum":"Describing Russell v. Marboro Books, 183 N.Y.S.2d 8 (Sup. Ct. 1959).","sumSrc":"brief:4","by":{"0":"27","4":"11"}},{"t":"case","label":"Landy v. Federal Deposit Insurance Corp.","cite":"486 F.2d 139","y":1973,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/486/139/","op":4,"by":{"0":"29"}},{"t":"case","label":"Monsen v. Consolidated Dressed Beef Co.","cite":"579 F.2d 793","y":1978,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/579/793/","op":3,"sum":"Stating a similar three-part test.","sumSrc":"opinion","by":{"0":"41","1":"28","2":"20","3":"67","4":"18"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","1":"22"}},{"t":"case","label":"Palmucci v. Twitter Inc.","cite":"2019 WL 1676079","y":2019,"court":"N.D. Cal. Apr. 17","by":{"0":"11"}},{"t":"case","label":"Pennie v. Twitter, Inc.","cite":"281 F. Supp. 3d 874","y":2017,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/281/874/","by":{"0":"11"}},{"t":"case","label":"Retana v. Twitter, Inc.","cite":"1 F.4th 378","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/378/","by":{"0":"11"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"op":5,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"0":"27","1":"28","3":"30","4":"5"}},{"t":"case","label":"Page(s) Rothstein v. UBS AG","cite":"708 F.3d 82","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/708/82/","op":1,"by":{"0":"8","1":"5","2":"2"}},{"t":"case","label":"Safeco Insurance Co. of America v. Burr","cite":"551 U.S. 47","y":2007,"id":"2006/06-84","sc":1,"sum":"The Court ruled that insurance companies can be liable for willful violations of the Fair Credit Reporting Act if they show \"reckless disregard\" for the law. The justices held that the meaning of the term \"willful\" is contextually determined.","sumSrc":"Oyez","by":{"0":"38, 44","1":"37, 39","4":"16"}},{"t":"case","label":"Schatz v. Rosenberg","cite":"943 F.2d 485","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/943/485/","by":{"0":"41"}},{"t":"case","label":"SEC v. Coffey","cite":"493 F.2d 1304","y":1974,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/493/1304/","by":{"0":"41","1":"28"}},{"t":"case","label":"SEC v. Fehn","cite":"97 F.3d 1276","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/97/1276/","by":{"0":"28"}},{"t":"case","label":"SEC v. Goble","cite":"682 F.3d 934","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/682/934/","by":{"0":"28"}},{"t":"case","label":"SEC v. Life Partner Holdings, Inc.","cite":"854 F.3d 765","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/854/765/","by":{"0":"28"}},{"t":"case","label":"Siegel v. HSBC North America Holdings, Inc.","cite":"933 F.3d 217","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/933/217/","ar":1,"by":{"0":"45, 46","1":"43"}},{"t":"case","label":"Sinclair for Tucker v. Twitter, Inc.","cite":"2019 WL 10252752","y":2019,"court":"N.D. Cal. Mar. 20","by":{"0":"11"}},{"t":"case","label":"Sony Corp. of America v. Universal City Studios, Inc.","cite":"464 U.S. 417","y":1984,"id":"1982/81-1687","sc":1,"sum":"The Court held that \"[t]he sale of the VTR's to the general public does not constitute contributory infringement of [Universal's] copyrights.\" The Court concluded that there was a significant likelihood that a substantial number of copyright holders who license their works for free public broadcasts would not object to having their broadcasts time-shifted by private viewers and that Universal failed to show that time-shifting would cause non-minimal harm to the potential market for, or the value of, their copyrighted works.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Tiffany (NJ) Inc. v. eBay Inc.","cite":"600 F.3d 93","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/600/93/","by":{"0":"42"}},{"t":"case","label":"Weiss v. National Westminster Bank, PLC","cite":"993 F.3d 144","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/993/144/","by":{"0":"46"}},{"t":"case","label":"Woodward v. Metro Bank of Dallas","cite":"522 F.2d 84","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/522/84/","op":7,"ar":1,"by":{"0":"10, 36, 38, 40, 41, 42","2":"19, 20","3":"68, 69, 70","4":"17, 18"}},{"t":"usc","label":"15 U.S.C. § 78t","url":"https://www.law.cornell.edu/uscode/text/15/78t","subs":["(e)"],"stext":{"head":"§78t. Liability of controlling persons and persons who aid and abet violations","paras":[[0,"(a) Joint and several liability; good faith defense"],[0,"Every person who, directly or indirectly, controls any person liable under any provision of this chapter or of any rule or regulation thereunder shall also be liable jointly and severally with and to the same extent as such controlled person to any person to whom such controlled person is liable (including to the Commission in any action brought under paragraph (1) or (3) of section 78u(d) of this title), unless the controlling person acted in good faith and did not directly or indirectly induce the act or acts constituting the violation or cause of action."],[0,"(b) Unlawful activity through or by means of any other person"],[0,"It shall be unlawful for any person, directly or indirectly, to do any act or thing which it would be unlawful for such person to do under the provisions of this chapter or any rule or regulation thereunder through or by means of any other person."],[0,"(c) Hindering, delaying, or obstructing the making or filing of any document, report, or information"],[0,"It shall be unlawful for any director or officer of, or any owner of any securities issued by, any issuer required to file any document, report, or information under this chapter or any rule or regulation thereunder without just cause to hinder, delay, or obstruct the making or filing of any such document, report, or information."],[0,"(d) Liability for trading in securities while in possession of material nonpublic information"],[0,"Wherever communicating, or purchasing or selling a security while in possession of, material nonpublic information would violate, or result in liability to any purchaser or seller of the security under any provisions of this chapter, or any rule or regulation thereunder, such conduct in connection with a purchase or sale of a put, call, straddle, option, privilege or security-based swap agreement with respect to such security or with respect to a group or index of securities including such security, shall also violate and result in comparable liability to any purchaser or seller of that security under such provision, rule, or regulation."],[0,"(e) Prosecution of persons who aid and abet violations"],[0,"For purposes of any action brought by the Commission under paragraph (1) or (3) of section 78u(d) of this title, any person that knowingly or recklessly provides substantial assistance to another person in violation of a provision of this chapter, or of any rule or regulation issued under this chapter, shall be deemed to be in violation of such provision to the same extent as the person to whom such assistance is provided."],[0,"(f) Limitation on Commission authority"],[0,"The authority of the Commission under this section with respect to security-based swap agreements shall be subject to the restrictions and limitations of section 78c–1(b) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78t?type=usc&year=mostrecent&link-type=html"},"head":"§78t. Liability of controlling persons and persons who aid and abet violations","tname":"Commerce and Trade","by":{"0":"28","1":"37","3":"39"}},{"t":"usc","label":"18 U.S.C. § 2331","url":"https://www.law.cornell.edu/uscode/text/18/2331","subs":["(a)","(1)"],"stext":{"head":"§2331. Definitions","paras":[[0,"As used in this chapter—"],[1,"(1) the term \"international terrorism\" means activities that—"],[2,"(A) involve violent acts or acts dangerous to human life that are a violation of the criminal laws of the United States or of any State, or that would be a criminal violation if committed within the jurisdiction of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily outside the territorial jurisdiction of the United States, or transcend national boundaries in terms of the means by which they are accomplished, the persons they appear intended to intimidate or coerce, or the locale in which their perpetrators operate or seek asylum;"],[1,"(2) the term \"national of the United States\" has the meaning given such term in section 101(a)(22) of the Immigration and Nationality Act;"],[1,"(3) the term \"person\" means any individual or entity capable of holding a legal or beneficial interest in property;"],[1,"(4) the term \"act of war\" means any act occurring in the course of—"],[2,"(A) declared war;"],[2,"(B) armed conflict, whether or not war has been declared, between two or more nations; or"],[2,"(C) armed conflict between military forces of any origin;"],[1,"(5) the term \"domestic terrorism\" means activities that—"],[2,"(A) involve acts dangerous to human life that are a violation of the criminal laws of the United States or of any State;"],[2,"(B) appear to be intended—"],[3,"(i) to intimidate or coerce a civilian population;"],[3,"(ii) to influence the policy of a government by intimidation or coercion; or"],[3,"(iii) to affect the conduct of a government by mass destruction, assassination, or kidnapping; and"],[2,"(C) occur primarily within the territorial jurisdiction of the United States; and"],[1,"(6) the term \"military force\" does not include any person that—"],[2,"(A) has been designated as a—"],[3,"(i) foreign terrorist organization by the Secretary of State under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189); or"],[3,"(ii) specially designated global terrorist (as such term is defined in section 594.310 of title 31, Code of Federal Regulations) by the Secretary of State or the Secretary of the Treasury; or"],[2,"(B) has been determined by the court to not be a \"military force\"."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2331?type=usc&year=mostrecent&link-type=html"},"head":"§2331. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"7","1":"5","2":"1, 2","3":"44"}},{"t":"usc","label":"18 U.S.C. § 2339A","url":"https://www.law.cornell.edu/uscode/text/18/2339A","by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 112-239","url":"https://www.govinfo.gov/link/plaw/112/public/239","by":{"0":"48"}},{"t":"law","label":"Pub. L. No. 114-222","url":"https://www.govinfo.gov/link/plaw/114/public/222","by":{"0":"3, 8, 9, 23, 33","1":"passim","2":"2","3":"48-51, 53, 54, 58, 62, 71, 77-79","4":"8, 10, 12"}},{"t":"case","label":"Benz v. Compania Naviera Hidalgo S.A.","cite":"353 U.S. 138","y":1957,"id":"1956/204","sc":1,"sum":"The Labor Management Relations Act of 1947 does not apply to a controversy involving damages resulting from the picketing of a foreign ship operated entirely by foreign seamen under foreign articles while the vessel is temporarily in an American port, though American unions to which the foreign seamen did not belong participated in the picketing; and the Act therefore does not preclude a remedy under state law for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Borden v. United States","cite":"141 S. Ct. 1817","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"37"}},{"t":"case","label":"F. Hoffmann-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"1":"48, 49"}},{"t":"case","label":"Libr. of Cong. v. Shaw","cite":"478 U.S. 310","y":1986,"id":"1985/85-54","sc":1,"sum":"The no-interest rule applies here so as to preclude the award of increased compensation to respondent's counsel for the delay in receiving payment for his services.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"McCulloch v. Sociedad Nacional de Marineros de Honduras","cite":"372 U.S. 10","y":1963,"id":"1962/107","sc":1,"sum":"The jurisdictional provisions of the National Labor Relations Act do not extend to the maritime operations of such foreign-flag ships employing alien seamen.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"case","label":"Morrison v. Nat’l Australia Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Owens v. BNP Paribas, S.A.","cite":"897 F.3d 266","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/897/266/","by":{"1":"5"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"World Wide Minerals, Ltd. v. Republic of Kazakhstan","cite":"296 F.3d 1154","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/296/1154/","ar":1,"by":{"1":"48"}},{"t":"case","label":"ZF Auto. US, Inc. v. Luxshare, Ltd.","cite":"142 S. Ct. 2078","y":2022,"id":"2021/21-401","sc":1,"sum":"Although 28 U. S. C. §1782(a) permits a district court to order discovery “for use in a proceeding in a foreign or international tribunal,” only a governmental or intergovernmental adjudicative body may qualify as such a tribunal, and the arbitration panels in these cases are not such adjudicative bodies.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"usc","label":"7 U.S.C. § 25","url":"https://www.law.cornell.edu/uscode/text/7/25","subs":["(a)","(a)(1)"],"stext":{"head":"§25. Private rights of action","paras":[[0,"(a) Actual damages; actionable transactions; exclusive remedy"],[0,"(1) Any person (other than a registered entity or registered futures association) who violates this chapter or who willfully aids, abets, counsels, induces, or procures the commission of a violation of this chapter shall be liable for actual damages resulting from one or more of the transactions referred to in subparagraphs (A) through (D) of this paragraph and caused by such violation to any other person—"],[1,"(A) who received trading advice from such person for a fee;"],[1,"(B) who made through such person any contract of sale of any commodity for future delivery (or option on such contract or any commodity) or any swap; or who deposited with or paid to such person money, securities, or property (or incurred debt in lieu thereof) in connection with any order to make such contract or any swap;"],[1,"(C) who purchased from or sold to such person or placed through such person an order for the purchase or sale of—"],[2,"(i) an option subject to section 6c of this title (other than an option purchased or sold on a registered entity or other board of trade);"],[2,"(ii) a contract subject to section 23 of this title; or 1"],[2,"(iii) an interest or participation in a commodity pool; or"],[2,"(iv) a swap; or"],[1,"(D) who purchased or sold a contract referred to in subparagraph (B) hereof or swap if the violation constitutes—"],[2,"(i) the use or employment of, or an attempt to use or employ, in connection with a swap, or a contract of sale of a commodity, in interstate commerce, or for future delivery on or subject to the rules of any registered entity, any manipulative device or contrivance in contravention of such rules and regulations as the Commission shall promulgate by not later than 1 year after July 21, 2010; or"],[2,"(ii) a manipulation of the price of any such contract or swap or the price of the commodity underlying such contract or swap."],[0,"(2) Except as provided in subsection (b), the rights of action authorized by this subsection and by sections 7(d)(13), 7a–1(c)(2)(H), and 21(b)(10) of this title shall be the exclusive remedies under this chapter available to any person who sustains loss as a result of any alleged violation of this chapter. Nothing in this subsection shall limit or abridge the rights of the parties to agree in advance of a dispute upon any forum for resolving claims under this section, including arbitration."],[0,"(3) In any action arising from a violation in the execution of an order on the floor of a registered entity, the person referred to in paragraph (1) shall be liable for—"],[1,"(A) actual damages proximately caused by such violation. If an award of actual damages is made against a floor broker in connection with the execution of a customer order, and the futures commission merchant which selected the floor broker for the execution of the customer order is held to be responsible under section 2(a)(1) of this title for the floor broker's violation, such futures commission merchant may be required to satisfy such award; and"],[1,"(B) where the violation is willful and intentional, punitive or exemplary damages equal to no more than two times the amount of such actual damages. If an award of punitive or exemplary damages is made against a floor broker in connection with the execution of a customer order, and the futures commission merchant which selected the floor broker for the execution of the customer order is held to be responsible under section 2(a)(1) of this title for the floor broker's violation, such futures commission merchant may be required to satisfy such award if the floor broker fails to do so, except that such requirement shall apply to the futures commission merchant only if it willfully and intentionally selected the floor broker with the intent to assist or facilitate the floor broker's violation."],[0,"(4) Contract enforcement between eligible counterparties.—"],[1,"(A) In general.—No hybrid instrument sold to any investor shall be void, voidable, or unenforceable, and no party to a hybrid instrument shall be entitled to rescind, or recover any payment made with respect to, the hybrid instrument under this section or any other provision of Federal or State law, based solely on the failure of the hybrid instrument to comply with the terms or conditions of section 2(f) of this title or regulations of the Commission."],[1,"(B) Swaps.—No agreement, contract, or transaction between eligible contract participants or persons reasonably believed to be eligible contract participants shall be void, voidable, or unenforceable, and no party to such agreement, contract, or transaction shall be entitled to rescind, or recover any payment made with respect to, the agreement, contract, or transaction under this section or any other provision of Federal or State law, based solely on the failure of the agreement, contract, or transaction—"],[2,"(i) to meet the definition of a swap under section 1a of this title; or"],[2,"(ii) to be cleared in accordance with section 2(h)(1) of this title."],[0,"(5) Legal certainty for long-term swaps entered into before July 21, 2010.—"],[1,"(A) Effect on swaps.—Unless specifically reserved in the applicable swap, neither the enactment of the Wall Street Transparency and Accountability Act of 2010, nor any requirement under that Act or an amendment made by that Act, shall constitute a termination event, force majeure, illegality, increased costs, regulatory change, or similar event under a swap (including any related credit support arrangement) that would permit a party to terminate, renegotiate, modify, amend, or supplement 1 or more transactions under the swap."],[1,"(B) Position limits.—Any position limit established under the Wall Street Transparency and Accountability Act of 2010 shall not apply to a position acquired in good faith prior to the effective date of any rule, regulation, or order under the Act that establishes the position limit; provided, however, that such positions shall be attributed to the trader if the trader's position is increased after the effective date of such position limit rule, regulation, or order."],[0,"(6) Contract enforcement for foreign futures contracts.—A contract of sale of a commodity for future delivery traded or executed on or through the facilities of a board of trade, exchange, or market located outside the United States for purposes of section 6(a) of this title shall not be void, voidable, or unenforceable, and a party to such a contract shall not be entitled to rescind or recover any payment made with respect to the contract, based on the failure of the foreign board of trade to comply with any provision of this chapter."],[0,"(b) Liabilities of organizations and individuals; bad faith requirement; exclusive remedy"],[0,"(1)(A) A registered entity that fails to enforce any bylaw, rule, regulation, or resolution that it is required to enforce by section 7, 7a–1, 7a–2, 7b–3, or 24a of this title, (B) a licensed board of trade that fails to enforce any bylaw, rule, regulation, or resolution that it is required to enforce by the Commission, or (C) any registered entity that in enforcing any such bylaw, rule, regulation, or resolution violates this chapter or any Commission rule, regulation, or order, shall be liable for actual damages sustained by a person who engaged in any transaction on or subject to the rules of such registered entity to the extent of such person's actual losses that resulted from such transaction and were caused by such failure to enforce or enforcement of such bylaws, rules, regulations, or resolutions."],[0,"(2) A registered futures association that fails to enforce any bylaw or rule that is required under section 21 of this title or in enforcing any such bylaw or rule violates this chapter or any Commission rule, regulation, or order shall be liable for actual damages sustained by a person that engaged in any transaction specified in subsection (a) of this section to the extent of such person's actual losses that resulted from such transaction and were caused by such failure to enforce or enforcement of such bylaw or rule."],[0,"(3) Any individual who, in the capacity as an officer, director, governor, committee member, or employee of registered 2 entity or a registered futures association willfully aids, abets, counsels, induces, or procures any failure by any such entity to enforce (or any violation of the chapter in enforcing) any bylaw, rule, regulation, or resolution referred to in paragraph (1) or (2) of this subsection, shall be liable for actual damages sustained by a person who engaged in any transaction specified in subsection (a) of this section on, or subject to the rules of, such registered entity or, in the case of an officer, director, governor, committee member, or employee of a registered futures association, any transaction specified in subsection (a) of this section, in either case to the extent of such person's actual losses that resulted from such transaction and were caused by such failure or violation."],[0,"(4) A person seeking to enforce liability under this section must establish that the registered entity 3 registered futures association, officer, director, governor, committee member, or employee acted in bad faith in failing to take action or in taking such action as was taken, and that such failure or action caused the loss."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/25?type=usc&year=mostrecent&link-type=html"},"head":"§25. Private rights of action","tname":"Agriculture","by":{"1":"27","3":"40"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)"],"by":{"1":"27"}},{"t":"usc","label":"8 U.S.C. § 1189","url":"https://www.law.cornell.edu/uscode/text/8/1189","subs":["(a)","(a)(1)(C)"],"stext":{"head":"§1189. Designation of foreign terrorist organizations","paras":[[0,"(a) Designation"],[0,"(1) In general"],[1,"The Secretary is authorized to designate an organization as a foreign terrorist organization in accordance with this subsection if the Secretary finds that—"],[2,"(A) the organization is a foreign organization;"],[2,"(B) the organization engages in terrorist activity (as defined in section 1182(a)(3)(B) of this title or terrorism (as defined in section 2656f(d)(2) of title 22), or retains the capability and intent to engage in terrorist activity or terrorism) 1; and"],[2,"(C) the terrorist activity or terrorism of the organization threatens the security of United States nationals or the national security of the United States."],[0,"(2) Procedure"],[0,"(A) Notice"],[0,"(i) To congressional leaders"],[3,"Seven days before making a designation under this subsection, the Secretary shall, by classified communication, notify the Speaker and Minority Leader of the House of Representatives, the President pro tempore, Majority Leader, and Minority Leader of the Senate, and the members of the relevant committees of the House of Representatives and the Senate, in writing, of the intent to designate an organization under this subsection, together with the findings made under paragraph (1) with respect to that organization, and the factual basis therefor."],[0,"(ii) Publication in Federal Register"],[3,"The Secretary shall publish the designation in the Federal Register seven days after providing the notification under clause (i)."],[0,"(B) Effect of designation"],[2,"(i) For purposes of section 2339B of title 18, a designation under this subsection shall take effect upon publication under subparagraph (A)(ii)."],[2,"(ii) Any designation under this subsection shall cease to have effect upon an Act of Congress disapproving such designation."],[0,"(C) Freezing of assets"],[2,"Upon notification under paragraph (2)(A)(i), the Secretary of the Treasury may require United States financial institutions possessing or controlling any assets of any foreign organization included in the notification to block all financial transactions involving those assets until further directive from either the Secretary of the Treasury, Act of Congress, or order of court."],[0,"(3) Record"],[0,"(A) In general"],[2,"In making a designation under this subsection, the Secretary shall create an administrative record."],[0,"(B) Classified information"],[2,"The Secretary may consider classified information in making a designation under this subsection. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(4) Period of designation"],[0,"(A) In general"],[2,"A designation under this subsection shall be effective for all purposes until revoked under paragraph (5) or (6) or set aside pursuant to subsection (c)."],[0,"(B) Review of designation upon petition"],[0,"(i) In general"],[3,"The Secretary shall review the designation of a foreign terrorist organization under the procedures set forth in clauses (iii) and (iv) if the designated organization files a petition for revocation within the petition period described in clause (ii)."],[0,"(ii) Petition period"],[3,"For purposes of clause (i)—"],[4,"(I) if the designated organization has not previously filed a petition for revocation under this subparagraph, the petition period begins 2 years after the date on which the designation was made; or"],[4,"(II) if the designated organization has previously filed a petition for revocation under this subparagraph, the petition period begins 2 years after the date of the determination made under clause (iv) on that petition."],[0,"(iii) Procedures"],[3,"Any foreign terrorist organization that submits a petition for revocation under this subparagraph must provide evidence in that petition that the relevant circumstances described in paragraph (1) are sufficiently different from the circumstances that were the basis for the designation such that a revocation with respect to the organization is warranted."],[0,"(iv) Determination"],[0,"(I) In general"],[4,"Not later than 180 days after receiving a petition for revocation submitted under this subparagraph, the Secretary shall make a determination as to such revocation."],[0,"(II) Classified information"],[4,"The Secretary may consider classified information in making a determination in response to a petition for revocation. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(III) Publication of determination"],[4,"A determination made by the Secretary under this clause shall be published in the Federal Register."],[0,"(IV) Procedures"],[4,"Any revocation by the Secretary shall be made in accordance with paragraph (6)."],[0,"(C) Other review of designation"],[0,"(i) In general"],[3,"If in a 5-year period no review has taken place under subparagraph (B), the Secretary shall review the designation of the foreign terrorist organization in order to determine whether such designation should be revoked pursuant to paragraph (6)."],[0,"(ii) Procedures"],[3,"If a review does not take place pursuant to subparagraph (B) in response to a petition for revocation that is filed in accordance with that subparagraph, then the review shall be conducted pursuant to procedures established by the Secretary. The results of such review and the applicable procedures shall not be reviewable in any court."],[0,"(iii) Publication of results of review"],[3,"The Secretary shall publish any determination made pursuant to this subparagraph in the Federal Register."],[0,"(5) Revocation by Act of Congress"],[1,"The Congress, by an Act of Congress, may block or revoke a designation made under paragraph (1)."],[0,"(6) Revocation based on change in circumstances"],[0,"(A) In general"],[2,"The Secretary may revoke a designation made under paragraph (1) at any time, and shall revoke a designation upon completion of a review conducted pursuant to subparagraphs (B) and (C) of paragraph (4) if the Secretary finds that—"],[3,"(i) the circumstances that were the basis for the designation have changed in such a manner as to warrant revocation; or"],[3,"(ii) the national security of the United States warrants a revocation."],[0,"(B) Procedure"],[2,"The procedural requirements of paragraphs (2) and (3) shall apply to a revocation under this paragraph. Any revocation shall take effect on the date specified in the revocation or upon publication in the Federal Register if no effective date is specified."],[0,"(7) Effect of revocation"],[1,"The revocation of a designation under paragraph (5) or (6) shall not affect any action or proceeding based on conduct committed prior to the effective date of such revocation."],[0,"(8) Use of designation in trial or hearing"],[1,"If a designation under this subsection has become effective under paragraph (2)(B) a defendant in a criminal action or an alien in a removal proceeding shall not be permitted to raise any question concerning the validity of the issuance of such designation as a defense or an objection at any trial or hearing."],[0,"(b) Amendments to a designation"],[0,"(1) In general"],[1,"The Secretary may amend a designation under this subsection if the Secretary finds that the organization has changed its name, adopted a new alias, dissolved and then reconstituted itself under a different name or names, or merged with another organization."],[0,"(2) Procedure"],[1,"Amendments made to a designation in accordance with paragraph (1) shall be effective upon publication in the Federal Register. Subparagraphs (B) and (C) of subsection (a)(2) shall apply to an amended designation upon such publication. Paragraphs (2)(A)(i), (4), (5), (6), (7), and (8) of subsection (a) shall also apply to an amended designation."],[0,"(3) Administrative record"],[1,"The administrative record shall be corrected to include the amendments as well as any additional relevant information that supports those amendments."],[0,"(4) Classified information"],[1,"The Secretary may consider classified information in amending a designation in accordance with this subsection. Classified information shall not be subject to disclosure for such time as it remains classified, except that such information may be disclosed to a court ex parte and in camera for purposes of judicial review under subsection (c)."],[0,"(c) Judicial review of designation"],[0,"(1) In general"],[1,"Not later than 30 days after publication in the Federal Register of a designation, an amended designation, or a determination in response to a petition for revocation, the designated organization may seek judicial review in the United States Court of Appeals for the District of Columbia Circuit."],[0,"(2) Basis of review"],[1,"Review under this subsection shall be based solely upon the administrative record, except that the Government may submit, for ex parte and in camera review, classified information used in making the designation, amended designation, or determination in response to a petition for revocation."],[0,"(3) Scope of review"],[1,"The Court shall hold unlawful and set aside a designation, amended designation, or determination in response to a petition for revocation the court finds to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1189?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1189. Designation of foreign terrorist organizations","tname":"Aliens and Nationality","by":{"1":"35","3":"43, 52, 44"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"26"}},{"t":"usc","label":"18 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/18/2333","subs":["(a)","(d)","(d)(2)"],"stext":{"head":"§2333. Civil remedies","paras":[[0,"(a) Action and Jurisdiction.—Any national of the United States injured in his or her person, property, or business by reason of an act of international terrorism, or his or her estate, survivors, or heirs, may sue therefor in any appropriate district court of the United States and shall recover threefold the damages he or she sustains and the cost of the suit, including attorney's fees."],[0,"(b) Estoppel Under United States Law.—A final judgment or decree rendered in favor of the United States in any criminal proceeding under section 1116, 1201, 1203, or 2332 of this title or section 46314, 46502, 46505, or 46506 of title 49 shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(c) Estoppel Under Foreign Law.—A final judgment or decree rendered in favor of any foreign state in any criminal proceeding shall, to the extent that such judgment or decree may be accorded full faith and credit under the law of the United States, estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(d) Liability.—"],[1,"(1) Definition.—In this subsection, the term \"person\" has the meaning given the term in section 1 of title 1."],[1,"(2) Liability.—In an action under subsection (a) for an injury arising from an act of international terrorism committed, planned, or authorized by an organization that had been designated as a foreign terrorist organization under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189), as of the date on which such act of international terrorism was committed, planned, or authorized, liability may be asserted as to any person who aids and abets, by knowingly providing substantial assistance, or who conspires with the person who committed such an act of international terrorism."],[0,"(e) Use of Blocked Assets to Satisfy Judgments of U.S. Nationals.—For purposes of section 201 of the Terrorism Risk Insurance Act of 2002 (28 U.S.C. 1610 note), in any action in which a national of the United States has obtained a judgment against a terrorist party pursuant to this section, the term \"blocked asset\" shall include any asset of that terrorist party (including the blocked assets of any agency or instrumentality of that party) seized or frozen by the United States under section 805(b) of the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1904(b))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2333?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§2333. Civil remedies","tname":"Crimes and Criminal Procedure","by":{"1":"passim, passim","2":"2, 3, 11, 31, 18, passim, 4, 11, 15, 33","3":"22, 47, 10, 20, 10, 38, 40-44, 47, 48, 50, 52-55, 58, 61, 65-67, 70","4":"2, 3, 6, 13, 15, 18, 24"}},{"t":"usc","label":"18 U.S.C. § 2339B","url":"https://www.law.cornell.edu/uscode/text/18/2339B","subs":["(a)","(a)(1)","(d)(1)(F)"],"stext":{"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","paras":[[0,"(a) Prohibited Activities.—"],[1,"(1) Unlawful conduct.—Whoever knowingly provides material support or resources to a foreign terrorist organization, or attempts or conspires to do so, shall be fined under this title or imprisoned not more than 20 years, or both, and, if the death of any person results, shall be imprisoned for any term of years or for life. To violate this paragraph, a person must have knowledge that the organization is a designated terrorist organization (as defined in subsection (g)(6)), that the organization has engaged or engages in terrorist activity (as defined in section 212(a)(3)(B) of the Immigration and Nationality Act), or that the organization has engaged or engages in terrorism (as defined in section 140(d)(2) of the Foreign Relations Authorization Act, Fiscal Years 1988 and 1989)."],[1,"(2) Financial institutions.—Except as authorized by the Secretary, any financial institution that becomes aware that it has possession of, or control over, any funds in which a foreign terrorist organization, or its agent, has an interest, shall—"],[2,"(A) retain possession of, or maintain control over, such funds; and"],[2,"(B) report to the Secretary the existence of such funds in accordance with regulations issued by the Secretary."],[0,"(b) Civil Penalty.—Any financial institution that knowingly fails to comply with subsection (a)(2) shall be subject to a civil penalty in an amount that is the greater of—"],[1,"(A) $50,000 per violation; or"],[1,"(B) twice the amount of which the financial institution was required under subsection (a)(2) to retain possession or control."],[0,"(c) Injunction.—Whenever it appears to the Secretary or the Attorney General that any person is engaged in, or is about to engage in, any act that constitutes, or would constitute, a violation of this section, the Attorney General may initiate civil action in a district court of the United States to enjoin such violation."],[0,"(d) Extraterritorial Jurisdiction.—"],[1,"(1) In general.—There is jurisdiction over an offense under subsection (a) if—"],[2,"(A) an offender is a national of the United States (as defined in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22))) or an alien lawfully admitted for permanent residence in the United States (as defined in section 101(a)(20) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(20)));"],[2,"(B) an offender is a stateless person whose habitual residence is in the United States;"],[2,"(C) after the conduct required for the offense occurs an offender is brought into or found in the United States, even if the conduct required for the offense occurs outside the United States;"],[2,"(D) the offense occurs in whole or in part within the United States;"],[2,"(E) the offense occurs in or affects interstate or foreign commerce; or"],[2,"(F) an offender aids or abets any person over whom jurisdiction exists under this paragraph in committing an offense under subsection (a) or conspires with any person over whom jurisdiction exists under this paragraph to commit an offense under subsection (a)."],[1,"(2) Extraterritorial jurisdiction.—There is extraterritorial Federal jurisdiction over an offense under this section."],[0,"(e) Investigations.—"],[1,"(1) In general.—The Attorney General shall conduct any investigation of a possible violation of this section, or of any license, order, or regulation issued pursuant to this section."],[1,"(2) Coordination with the department of the treasury.—The Attorney General shall work in coordination with the Secretary in investigations relating to—"],[2,"(A) the compliance or noncompliance by a financial institution with the requirements of subsection (a)(2); and"],[2,"(B) civil penalty proceedings authorized under subsection (b)."],[1,"(3) Referral.—Any evidence of a criminal violation of this section arising in the course of an investigation by the Secretary or any other Federal agency shall be referred immediately to the Attorney General for further investigation. The Attorney General shall timely notify the Secretary of any action taken on referrals from the Secretary, and may refer investigations to the Secretary for remedial licensing or civil penalty action."],[0,"(f) Classified Information in Civil Proceedings Brought by the United States.—"],[1,"(1) Discovery of classified information by defendants.—"],[2,"(A) Request by united states.—In any civil proceeding under this section, upon request made ex parte and in writing by the United States, a court, upon a sufficient showing, may authorize the United States to—"],[3,"(i) redact specified items of classified information from documents to be introduced into evidence or made available to the defendant through discovery under the Federal Rules of Civil Procedure;"],[3,"(ii) substitute a summary of the information for such classified documents; or"],[3,"(iii) substitute a statement admitting relevant facts that the classified information would tend to prove."],[2,"(B) Order granting request.—If the court enters an order granting a request under this paragraph, the entire text of the documents to which the request relates shall be sealed and preserved in the records of the court to be made available to the appellate court in the event of an appeal."],[2,"(C) Denial of request.—If the court enters an order denying a request of the United States under this paragraph, the United States may take an immediate, interlocutory appeal in accordance with paragraph (5). For purposes of such an appeal, the entire text of the documents to which the request relates, together with any transcripts of arguments made ex parte to the court in connection therewith, shall be maintained under seal and delivered to the appellate court."],[1,"(2) Introduction of classified information; precautions by court.—"],[2,"(A) Exhibits.—To prevent unnecessary or inadvertent disclosure of classified information in a civil proceeding brought by the United States under this section, the United States may petition the court ex parte to admit, in lieu of classified writings, recordings, or photographs, one or more of the following:"],[3,"(i) Copies of items from which classified information has been redacted."],[3,"(ii) Stipulations admitting relevant facts that specific classified information would tend to prove."],[3,"(iii) A declassified summary of the specific classified information."],[2,"(B) Determination by court.—The court shall grant a request under this paragraph if the court finds that the redacted item, stipulation, or summary is sufficient to allow the defendant to prepare a defense."],[1,"(3) Taking of trial testimony.—"],[2,"(A) Objection.—During the examination of a witness in any civil proceeding brought by the United States under this subsection, the United States may object to any question or line of inquiry that may require the witness to disclose classified information not previously found to be admissible."],[2,"(B) Action by court.—In determining whether a response is admissible, the court shall take precautions to guard against the compromise of any classified information, including—"],[3,"(i) permitting the United States to provide the court, ex parte, with a proffer of the witness's response to the question or line of inquiry; and"],[3,"(ii) requiring the defendant to provide the court with a proffer of the nature of the information that the defendant seeks to elicit."],[2,"(C) Obligation of defendant.—In any civil proceeding under this section, it shall be the defendant's obligation to establish the relevance and materiality of any classified information sought to be introduced."],[1,"(4) Appeal.—If the court enters an order denying a request of the United States under this subsection, the United States may take an immediate interlocutory appeal in accordance with paragraph (5)."],[1,"(5) Interlocutory appeal.—"],[2,"(A) Subject of appeal.—An interlocutory appeal by the United States shall lie to a court of appeals from a decision or order of a district court—"],[3,"(i) authorizing the disclosure of classified information;"],[3,"(ii) imposing sanctions for nondisclosure of classified information; or"],[3,"(iii) refusing a protective order sought by the United States to prevent the disclosure of classified information."],[2,"(B) Expedited consideration.—"],[3,"(i) In general.—An appeal taken pursuant to this paragraph, either before or during trial, shall be expedited by the court of appeals."],[3,"(ii) Appeals prior to trial.—If an appeal is of an order made prior to trial, an appeal shall be taken not later than 14 days after the decision or order appealed from, and the trial shall not commence until the appeal is resolved."],[3,"(iii) Appeals during trial.—If an appeal is taken during trial, the trial court shall adjourn the trial until the appeal is resolved, and the court of appeals—"],[4,"(I) shall hear argument on such appeal not later than 4 days after the adjournment of the trial, excluding intermediate weekends and holidays;"],[4,"(II) may dispense with written briefs other than the supporting materials previously submitted to the trial court;"],[4,"(III) shall render its decision not later than 4 days after argument on appeal, excluding intermediate weekends and holidays; and"],[4,"(IV) may dispense with the issuance of a written opinion in rendering its decision."],[2,"(C) Effect of ruling.—An interlocutory appeal and decision shall not affect the right of the defendant, in a subsequent appeal from a final judgment, to claim as error reversal by the trial court on remand of a ruling appealed from during trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2339B?type=usc&year=mostrecent&link-type=html"},"head":"§2339B. Providing material support or resources to designated foreign terrorist organizations","tname":"Crimes and Criminal Procedure","by":{"1":"5, 33, 12, 25","2":"3, 18, 21, 32","3":"48, 49, 64, 48, 41"}},{"t":"usc","label":"28 U.S.C. § 1605B","url":"https://www.law.cornell.edu/uscode/text/28/1605B","subs":["(b)","(c)","(d)"],"stext":{"head":"§1605B. Responsibility of foreign states for international terrorism against the United States","paras":[[0,"(a) Definition.—In this section, the term \"international terrorism\"—"],[1,"(1) has the meaning given the term in section 2331 of title 18, United States Code; and"],[1,"(2) does not include any act of war (as defined in that section)."],[0,"(b) Responsibility of Foreign States.—A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which money damages are sought against a foreign state for physical injury to person or property or death occurring in the United States and caused by—"],[1,"(1) an act of international terrorism in the United States; and"],[1,"(2) a tortious act or acts of the foreign state, or of any official, employee, or agent of that foreign state while acting within the scope of his or her office, employment, or agency, regardless where the tortious act or acts of the foreign state occurred."],[0,"(c) Claims by Nationals of the United States.—Notwithstanding section 2337(2) of title 18, a national of the United States may bring a claim against a foreign state in accordance with section 2333 of that title if the foreign state would not be immune under subsection (b)."],[0,"(d) Rule of Construction.—A foreign state shall not be subject to the jurisdiction of the courts of the United States under subsection (b) on the basis of an omission or a tortious act or acts that constitute mere negligence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605B?type=usc&year=mostrecent&link-type=html"},"head":"§1605B. Responsibility of foreign states for international terrorism against the United States","tname":"Judiciary and Judicial Procedure","by":{"1":"47, 47","2":"26, 26, 26, 26","4":"10"}},{"t":"usc","label":"47 U.S.C. § 230","url":"https://www.law.cornell.edu/uscode/text/47/230","stext":{"head":"§230. Protection for private blocking and screening of offensive material","paras":[[0,"(a) Findings"],[0,"The Congress finds the following:"],[1,"(1) The rapidly developing array of Internet and other interactive computer services available to individual Americans represent an extraordinary advance in the availability of educational and informational resources to our citizens."],[1,"(2) These services offer users a great degree of control over the information that they receive, as well as the potential for even greater control in the future as technology develops."],[1,"(3) The Internet and other interactive computer services offer a forum for a true diversity of political discourse, unique opportunities for cultural development, and myriad avenues for intellectual activity."],[1,"(4) The Internet and other interactive computer services have flourished, to the benefit of all Americans, with a minimum of government regulation."],[1,"(5) Increasingly Americans are relying on interactive media for a variety of political, educational, cultural, and entertainment services."],[0,"(b) Policy"],[0,"It is the policy of the United States—"],[1,"(1) to promote the continued development of the Internet and other interactive computer services and other interactive media;"],[1,"(2) to preserve the vibrant and competitive free market that presently exists for the Internet and other interactive computer services, unfettered by Federal or State regulation;"],[1,"(3) to encourage the development of technologies which maximize user control over what information is received by individuals, families, and schools who use the Internet and other interactive computer services;"],[1,"(4) to remove disincentives for the development and utilization of blocking and filtering technologies that empower parents to restrict their children's access to objectionable or inappropriate online material; and"],[1,"(5) to ensure vigorous enforcement of Federal criminal laws to deter and punish trafficking in obscenity, stalking, and harassment by means of computer."],[0,"(c) Protection for \"Good Samaritan\" blocking and screening of offensive material"],[0,"(1) Treatment of publisher or speaker"],[1,"No provider or user of an interactive computer service shall be treated as the publisher or speaker of any information provided by another information content provider."],[0,"(2) Civil liability"],[1,"No provider or user of an interactive computer service shall be held liable on account of—"],[2,"(A) any action voluntarily taken in good faith to restrict access to or availability of material that the provider or user considers to be obscene, lewd, lascivious, filthy, excessively violent, harassing, or otherwise objectionable, whether or not such material is constitutionally protected; or"],[2,"(B) any action taken to enable or make available to information content providers or others the technical means to restrict access to material described in paragraph (1).1"],[0,"(d) Obligations of interactive computer service"],[0,"A provider of interactive computer service shall, at the time of entering an agreement with a customer for the provision of interactive computer service and in a manner deemed appropriate by the provider, notify such customer that parental control protections (such as computer hardware, software, or filtering services) are commercially available that may assist the customer in limiting access to material that is harmful to minors. Such notice shall identify, or provide the customer with access to information identifying, current providers of such protections."],[0,"(e) Effect on other laws"],[0,"(1) No effect on criminal law"],[1,"Nothing in this section shall be construed to impair the enforcement of section 223 or 231 of this title, chapter 71 (relating to obscenity) or 110 (relating to sexual exploitation of children) of title 18, or any other Federal criminal statute."],[0,"(2) No effect on intellectual property law"],[1,"Nothing in this section shall be construed to limit or expand any law pertaining to intellectual property."],[0,"(3) State law"],[1,"Nothing in this section shall be construed to prevent any State from enforcing any State law that is consistent with this section. No cause of action may be brought and no liability may be imposed under any State or local law that is inconsistent with this section."],[0,"(4) No effect on communications privacy law"],[1,"Nothing in this section shall be construed to limit the application of the Electronic Communications Privacy Act of 1986 or any of the amendments made by such Act, or any similar State law."],[0,"(5) No effect on sex trafficking law"],[1,"Nothing in this section (other than subsection (c)(2)(A)) shall be construed to impair or limit—"],[2,"(A) any claim in a civil action brought under section 1595 of title 18, if the conduct underlying the claim constitutes a violation of section 1591 of that title;"],[2,"(B) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 1591 of title 18; or"],[2,"(C) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 2421A of title 18, and promotion or facilitation of prostitution is illegal in the jurisdiction where the defendant's promotion or facilitation of prostitution was targeted."],[0,"(f) Definitions"],[0,"As used in this section:"],[0,"(1) Internet"],[1,"The term \"Internet\" means the international computer network of both Federal and non-Federal interoperable packet switched data networks."],[0,"(2) Interactive computer service"],[1,"The term \"interactive computer service\" means any information service, system, or access software provider that provides or enables computer access by multiple users to a computer server, including specifically a service or system that provides access to the Internet and such systems operated or services offered by libraries or educational institutions."],[0,"(3) Information content provider"],[1,"The term \"information content provider\" means any person or entity that is responsible, in whole or in part, for the creation or development of information provided through the Internet or any other interactive computer service."],[0,"(4) Access software provider"],[1,"The term \"access software provider\" means a provider of software (including client or server software), or enabling tools that do any one or more of the following:"],[2,"(A) filter, screen, allow, or disallow content;"],[2,"(B) pick, choose, analyze, or digest content; or"],[2,"(C) transmit, receive, display, forward, cache, search, subset, organize, reorganize, or translate content."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/230?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§230. Protection for private blocking and screening of offensive material","tname":"Telecommunications","by":{"1":"11","2":"8"}},{"t":"law","label":"Pub. L. No. 101-519","url":"https://www.govinfo.gov/link/statute/104/2240","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 102-572","url":"https://www.govinfo.gov/link/statute/106/4506","by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"5"}},{"t":"case","label":"Abbott v. Equity Grp., Inc.","cite":"2 F.3d 613","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/2/613/","by":{"2":"20"}},{"t":"case","label":"Atchley v. AstraZeneca UK Limited","cite":"22 F.4th 204","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/22/204/","ar":6,"sum":"Holding that a defendant could be held secondarily liable for “financially fortifying” entities known to be affiliated with foreign terrorist organizations through atypical transactions because such actions would foreseeably result in acts of terrorism.","sumSrc":"brief:2","by":{"2":"22, 34","3":"18, 25"}},{"t":"case","label":"Gonzalez v. Google","cite":"2 F.4th 871","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/2/871/","op":3,"ar":1,"sum":"Holding that a defendant could be held secondarily liable for “financially fortifying” entities known to be affiliated with foreign terrorist organizations through atypical transactions because such actions would foreseeably result in acts of terrorism.","sumSrc":"brief:2","by":{"2":"8"}},{"t":"case","label":"Metge v. Baehler","cite":"762 F.2d 621","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/762/621/","by":{"2":"28"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"by":{"2":"19"}},{"t":"case","label":"Bozza v. U.S.","cite":"330 U.S. 160","y":1947,"id":"scdb/1946-053","sc":1,"sum":"The Government's concession that the evidence was insufficient to sustain his conviction is accepted.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Coffin v. U.S.","cite":"162 U.S. 664","y":1896,"id":"scdb/1895-213","sc":1,"sum":"Goffin v. United States, 156 U. S. 432, affirmed on the following points:","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Evans v. U.S.","cite":"153 U.S. 584","y":1894,"id":"scdb/1893-256","sc":1,"sum":"An indictment should charge the crime, alleged to have been committed, with precision and certainty, and every ingredient of which it is composed must be accurately and clearly alleged; but it is not necessary in framing it to set up an impracticable standard of particularity, whereby the government may be entrapped into making allegations which it would' be impossible to prove.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Hicks v. U.S.","cite":"150 U.S. 442","y":1893,"id":"scdb/1893-055","sc":1,"sum":"H..was indicted jointly with. R. for the murder of C. Before the clay of trial R. was killed, whereupon H. was tried separately. It was clearly proved at the trial.that H. did not kill C. nor take any part in the physi- cal struggle which resulted in his death at the hands of R. There was' evidence tending-to show that by his language and gestures H. abetted R., but this evidence was given by persons who stood at …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Honickman v. BLOM Bank SAL","cite":"6 F.4th 487","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/6/487/","by":{"3":"18, 25, 29"}},{"t":"case","label":"Iqbal v. Twombly","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"3":"72"}},{"t":"case","label":"Nye & Nisssen v. U.S.","cite":"336 U.S. 613","y":1949,"id":"scdb/1948-062","sc":1,"op":8,"sum":"Petitioners are a corporation and its president. An indictment charged them (and three employees of the corporation), in the first count, with conspiracy to defraud the United States from 1938 to 1945, in violation of § 37 of the Criminal Code (now 18 U. S. C. § 371); and, in six substantive counts, with filing false invoices with an agency of the United States, in violation of § 35 of the Criminal Code (now 18 U. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"People’s Mojahedin Org. of Iran v. U.S. Dept. of State","cite":"182 F.3d 17","y":1999,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/182/17/","by":{"3":"43"}},{"t":"case","label":"Shuttlesworth v. City of Birmingham, Ala.","cite":"373 U.S. 262","y":1963,"id":"1962/67","sc":1,"sum":"Since those convictions have been set aside, it follows that these petitioners did not incite or aid and abet any crime, and that, therefore, the convictions of these petitioners must also be set aside. Pp. 263-266. 41 Ala. App. 318, 319, 134 So. 2d 213, 215, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Standefer v. U.S.","cite":"447 U.S. 10","y":1980,"id":"1979/79-383","sc":1,"sum":"A defendant accused of aiding and abetting in the commission of a federal offense may properly be convicted despite the prior acquittal of the alleged actual perpetrator of the offense.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"U.S. v. Williams","cite":"341 U.S. 58","y":1991,"id":"scdb/1950-062","sc":1,"sum":"In a prosecution for violation of what is now 18 U. S. C. § 242, arising out of the alleged beating of persons to coerce confessions, and for conspiracy against Fourteenth Amendment rights of citizens in alleged violation of what is now 18 U. S. C. § 241, appellee Williams was convicted and the other three appellees were acquitted of the substantive offenses, and the jury was unable to agree on a verdict on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"39"}},{"t":"case","label":"Weiss v. National Westminster Bank, PLC","cite":"142 S. Ct. 2866","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./142/2866/","sc":1,"by":{"3":"19, 38, 48"}},{"t":"case","label":"Weiss v. National Westminster Bank, PLC","cite":"993 F.2d 144","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/993/144/","by":{"3":"49, 71"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"3":"48","4":"4"}},{"t":"usc","label":"5 U.S.C. § 7313","url":"https://www.law.cornell.edu/uscode/text/5/7313","subs":["(a)(3)"],"by":{"3":"41"}},{"t":"usc","label":"6 U.S.C. § 411","url":"https://www.law.cornell.edu/uscode/text/6/411","subs":["(a)(1)(B)"],"by":{"3":"70"}},{"t":"usc","label":"7 U.S.C. § 2009cc-14","url":"https://www.law.cornell.edu/uscode/text/7/2009cc-14","subs":["(a)"],"by":{"3":"40"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)(1)(A)(v)(II)"],"by":{"3":"40"}},{"t":"usc","label":"15 U.S.C. § 687f","url":"https://www.law.cornell.edu/uscode/text/15/687f","subs":["(a)"],"by":{"3":"40"}},{"t":"usc","label":"15 U.S.C. § 689","url":"https://www.law.cornell.edu/uscode/text/15/689","subs":["(a)"],"by":{"3":"40"}},{"t":"usc","label":"15 U.S.C. § 1681d","url":"https://www.law.cornell.edu/uscode/text/15/1681d","subs":["(d)(4)(A)"],"by":{"3":"70"}},{"t":"usc","label":"18 U.S.C. § 175c","url":"https://www.law.cornell.edu/uscode/text/18/175c","subs":["(b)(5)"],"by":{"3":"41"}},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(b)(1)(B)","(b)(2)(B)"],"by":{"3":"40, 40"}},{"t":"usc","label":"18 U.S.C. § 226","url":"https://www.law.cornell.edu/uscode/text/18/226","subs":["(a)(1)(A)"],"by":{"3":"40"}},{"t":"usc","label":"18 U.S.C. § 1992","url":"https://www.law.cornell.edu/uscode/text/18/1992","subs":["(c)(2)"],"by":{"3":"40"}},{"t":"usc","label":"18 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/18/2101","subs":["(a)(1)"],"by":{"3":"41"}},{"t":"usc","label":"18 U.S.C. § 2332g","url":"https://www.law.cornell.edu/uscode/text/18/2332g","subs":["(h)(b)(5)"],"by":{"3":"41"}},{"t":"usc","label":"18 U.S.C. § 2332h","url":"https://www.law.cornell.edu/uscode/text/18/2332h","subs":["(b)(5)"],"by":{"3":"41"}},{"t":"usc","label":"18 U.S.C. § 2339D","url":"https://www.law.cornell.edu/uscode/text/18/2339D","subs":["(b)(6)"],"by":{"3":"41"}},{"t":"usc","label":"19 U.S.C. § 1415","url":"https://www.law.cornell.edu/uscode/text/19/1415","subs":["(a)(3)(B)"],"by":{"3":"70"}},{"t":"usc","label":"22 U.S.C. § 6723","url":"https://www.law.cornell.edu/uscode/text/22/6723","subs":["(b)(3)(A)(i)"],"by":{"3":"40"}},{"t":"usc","label":"22 U.S.C. § 7708","url":"https://www.law.cornell.edu/uscode/text/22/7708","subs":["(b)(4)"],"by":{"3":"40"}},{"t":"usc","label":"42 U.S.C. § 256","url":"https://www.law.cornell.edu/uscode/text/42/256","subs":["(b)"],"by":{"3":"70"}},{"t":"usc","label":"42 U.S.C. § 2122","url":"https://www.law.cornell.edu/uscode/text/42/2122","subs":["(b)(4)"],"by":{"3":"41"}},{"t":"usc","label":"50 U.S.C. § 1705","url":"https://www.law.cornell.edu/uscode/text/50/1705","subs":["(c)"],"by":{"3":"41"}},{"t":"usc","label":"50 U.S.C. § 4819","url":"https://www.law.cornell.edu/uscode/text/50/4819","subs":["(b)"],"by":{"3":"41"}},{"t":"usc","label":"50 U.S.C. § 4843","url":"https://www.law.cornell.edu/uscode/text/50/4843","subs":["(a)"],"by":{"3":"41"}},{"t":"case","label":"Brown v. Davenport","cite":"142 S. Ct. 1510","y":2022,"id":"2021/20-826","sc":1,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"12"}},{"t":"case","label":"Cobb v. Indian Springs, Inc.","cite":"522 S.W.2d 383","y":1975,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/522/383/","sum":"Describing Russell v. Marboro Books, 183 N.Y.S.2d 8 (Sup. Ct. 1959).","sumSrc":"brief:4","by":{"4":"11"}},{"t":"case","label":"Global-Tech Appliances, Inc. v. SEB S.A.","cite":"563 U.S. 754","y":2011,"id":"2010/10-6","sc":1,"sum":"The Court ruled that induced infringement under the patent clause requires knowledge that the induced acts constitute patent infringement.","sumSrc":"Oyez","by":{"4":"17"}},{"t":"case","label":"Rael v. Cadena","cite":"604 P.2d 822","y":1979,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/604/822/","by":{"4":"11"}},{"t":"case","label":"Russell v. Marboro Books","cite":"183 N.Y.S.2d 8","y":1959,"court":"Sup. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/183/8/","by":{"4":"11"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"4":"11"}},{"t":"case","label":"Page(s) Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"8"}}]};